CREATE TABLE savings_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, title text NOT NULL, emoji text NOT NULL DEFAULT '🎯', target numeric(14,2) NOT NULL, currency char(3) NOT NULL DEFAULT 'CZK', saved numeric(14,2) NOT NULL DEFAULT 0, source text NOT NULL DEFAULT 'manual', deadline date, created_at timestamptz NOT NULL DEFAULT now());
